    -- Noclip Toggle
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local player = Players.LocalPlayer
    local ClipOn = false
    local NoclipConnection

    local function ApplyNoclip(state)
        local character = player.Character
        if not character then return end
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                part.CanCollide = not state
            end
        end
    end

    local function SetNoclip(enabled)
        ClipOn = enabled
        if NoclipConnection then
            NoclipConnection:Disconnect()
            NoclipConnection = nil
        end
        if ClipOn then
            NoclipConnection = RunService.Heartbeat:Connect(function()
                ApplyNoclip(true)
            end)
        else
            ApplyNoclip(false)
        end
    end

    player.CharacterAdded:Connect(function()
        task.wait(0.2)
        if ClipOn then
            SetNoclip(true)
        end
    end)

    Miscs:Toggle({
        Title = "Noclip",
        Default = false,
        Callback = function(state)
            SetNoclip(state)
        end
    })


--====================
-- Anti Fling Toggle (FIXED)
--====================

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

local AntiFlingEnabled = false
local Connections = {}

--====================
-- Wait for load
--====================
if not game:IsLoaded() then
	game.Loaded:Wait()
end

local function WaitCharacter(plr)
	if not plr.Character then
		plr.CharacterAdded:Wait()
	end
	plr.Character:WaitForChild("Humanoid")
	plr.Character:WaitForChild("Head")
end

WaitCharacter(LocalPlayer)

--====================
-- Constraint handler
--====================
local function CheckInstance(Part)
	if not AntiFlingEnabled then return end
	if not Part:IsA("BasePart") then return end

	for _, lpPart in pairs(LocalPlayer.Character:GetDescendants()) do
		if lpPart:IsA("BasePart") then
			local NCC = Instance.new("NoCollisionConstraint")
			NCC.Part0 = Part
			NCC.Part1 = lpPart
			NCC.Enabled = true
			NCC.Parent = Part
		end
	end
end

--====================
-- Insert logic
--====================
local function Insert(Target)
	if not AntiFlingEnabled then return end

	WaitCharacter(Target)

	-- clear existing
	for _, v in pairs(Target.Character:GetDescendants()) do
		if v:IsA("NoCollisionConstraint") then
			v:Destroy()
		end
	end

	-- apply
	for _, v in pairs(Target.Character:GetDescendants()) do
		CheckInstance(v)
	end

	table.insert(Connections,
		Target.Character.DescendantAdded:Connect(function(v)
			if AntiFlingEnabled then
				CheckInstance(v)
			end
		end)
	)
end

--====================
-- Enable
--====================
local function EnableAntiFling()
	if AntiFlingEnabled then return end
	AntiFlingEnabled = true

	for _, plr in pairs(Players:GetPlayers()) do
		if plr ~= LocalPlayer then
			Insert(plr)
		end
	end

	table.insert(Connections,
		Players.PlayerAdded:Connect(function(plr)
			if AntiFlingEnabled then
				Insert(plr)
			end
		end)
	)

	table.insert(Connections,
		LocalPlayer.CharacterAdded:Connect(function()
			if not AntiFlingEnabled then return end
			task.wait(1)
			for _, plr in pairs(Players:GetPlayers()) do
				if plr ~= LocalPlayer then
					Insert(plr)
				end
			end
		end)
	)
end

--====================
-- Disable (REAL OFF)
--====================
local function DisableAntiFling()
	if not AntiFlingEnabled then return end
	AntiFlingEnabled = false

	-- disconnect all
	for _, con in pairs(Connections) do
		pcall(function()
			con:Disconnect()
		end)
	end
	table.clear(Connections)

	-- remove ALL constraints
	for _, plr in pairs(Players:GetPlayers()) do
		if plr.Character then
			for _, v in pairs(plr.Character:GetDescendants()) do
				if v:IsA("NoCollisionConstraint") then
					v:Destroy()
				end
			end
		end
	end
end

