-- WIND UI INTEGRATION: INSTANT CAMERA-BASED FLIGHT
--==================================================

-- SERVICES
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local camera = workspace.CurrentCamera
local player = Players.LocalPlayer

-- CHARACTER SETUP
local character, humanoid, rootPart
local function setupCharacter(char)
	character = char
	humanoid = char:WaitForChild("Humanoid")
	rootPart = char:WaitForChild("HumanoidRootPart")
end
setupCharacter(player.Character or player.CharacterAdded:Wait())
player.CharacterAdded:Connect(setupCharacter)

-- FLIGHT VARIABLES
local flying = false
local flySpeed = 120
local DefaultFlySpeed = 120
local bodyVelocity, bodyGyro

-- FLIGHT FUNCTIONS
local function startFlight()
	if flying then return end
	flying = true
	humanoid.PlatformStand = true

	bodyVelocity = Instance.new("BodyVelocity")
	bodyVelocity.MaxForce = Vector3.new(1e9,1e9,1e9)
	bodyVelocity.Velocity = Vector3.zero
	bodyVelocity.Parent = rootPart

	bodyGyro = Instance.new("BodyGyro")
	bodyGyro.MaxTorque = Vector3.new(1e9,1e9,1e9)
	bodyGyro.P = 12000
	bodyGyro.D = 800
	bodyGyro.Parent = rootPart
end

local function stopFlight()
	if not flying then return end
	flying = false
	humanoid.PlatformStand = false
	if bodyVelocity then bodyVelocity:Destroy() end
	if bodyGyro then bodyGyro:Destroy() end
end

local function toggleFlight()
	if flying then
		stopFlight()
	else
		startFlight()
	end
end

-- Toggle Flight
Miscs:Toggle({
    Title = "Fly",
    Default = false,
    Callback = function(value)
        if value then
            startFlight()
        else
            stopFlight()
        end
    end
})

-- Flight Speed Input (Wind UI style like Gravity)
Miscs:Input({
    Title = "Fly Speed",
    Desc = tostring(DefaultFlySpeed).." -- Default flight speed",
    Width = 200,
    Callback = function(value)
        local num = tonumber(value)
        if num and num > 0 then
            flySpeed = num
        else
            flySpeed = DefaultFlySpeed
        end
    end
})

-- FLIGHT LOOP (INSTANT CAMERA-BASED MOVEMENT)
RunService.RenderStepped:Connect(function()
	if not flying or not humanoid or not rootPart then return end

	-- Face camera instantly
	bodyGyro.CFrame = camera.CFrame

	local move = Vector3.zero
	local dir = humanoid.MoveDirection

	if dir.Magnitude > 0 then
		move += dir.Unit
	end

	-- Vertical movement logic:
	local lookY = camera.CFrame.LookVector.Y
	-- Forward + looking up → fly up
	if dir.Z > 0 and lookY > 0 then
		move += Vector3.new(0, lookY, 0)
	-- Backward + looking down → fly down
	elseif dir.Z < 0 and lookY < 0 then
		move += Vector3.new(0, lookY, 0)
	end

	if move.Magnitude > 0 then
		move = move.Unit * flySpeed
	end

	bodyVelocity.Velocity = move
end)

Miscs:Space()

Miscs:Button({ Title = "FE JERK TOOL (R6)", Callback = function()
        loadstring(game:HttpGet("https://pastefy.app/wa3v2Vgm/raw"))()
    end })

